function getStylePromptData(styleId) {
  return STYLE_PROMPT_DATA[styleId] || null;
}

function buildStylePromptText(style, options = {}) {
  const language = options.language === "en" ? "en" : "zh";
  const data = getStylePromptData(style.id);
  if (!data) return "";
  const intensity = options.intensity || "明显";
  const styleName = language === "zh" ? style.nameZh : style.nameEn;
  const direction = STYLE_PROMPT_POLICY.intensity[language][intensity].replace("{name}", styleName);
  const sourceGenes = Array.isArray(options.activeGenes) ? options.activeGenes : data.genes;
  const promptKey = language === "zh" ? "promptZh" : "promptEn";
  const geneText = sourceGenes.map((gene) => gene[promptKey]).filter(Boolean).join(language === "zh" ? "；" : "; " );
  const parts = [
    direction,
    STYLE_PROMPT_POLICY.content[language],
    geneText ? STYLE_PROMPT_POLICY.executionLead[language] + geneText : ""
  ].filter(Boolean);
  return parts.join(language === "zh" ? "。" : ". " ) + (language === "zh" ? "。" : ".");
}

function buildStyleNegativeText(language = "zh") {
  return STYLE_PROMPT_POLICY.negative[language === "en" ? "en" : "zh"];
}
